body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: #f9fafb;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    margin: 0;
}

.container {
    background: white;
    padding: 2rem;
    border-radius: 8px;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    width: 100%;
    max-width: 400px;
}

h1 {
    font-size: 1.5rem;
    font-weight: 600;
    color: #111827;
    margin-bottom: 1.5rem;
}

.form-field {
    margin-bottom: 1.5rem;
}

.checkbox-container {
    display: flex;
    align-items: flex-start;
    gap: 0.75rem;
}

input[type="checkbox"] {
    width: 1.25rem;
    height: 1.25rem;
    cursor: pointer;
    margin-top: 0.2rem;
}

.label-text {
    font-size: 0.875rem;
    color: #374151;
    line-height: 1.5;
}

.helper-text {
    font-size: 0.75rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

button {
    width: 100%;
    background-color: #2563eb;
    color: white;
    padding: 0.75rem;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.2s;
}

button:hover {
    background-color: #1d4ed8;
}

button:disabled {
    background-color: #93c5fd;
    cursor: not-allowed;
}

const { useState } = React;

function ConsentForm() {
    const [agreed, setAgreed] = useState(false);

    const handleSubmit = (e) => {
        e.preventDefault();
        alert('Form submitted successfully!');
    };

    return (
        <div className="container">
            <h1>Create Account</h1>
            <form onSubmit={handleSubmit}>
                <div className="form-field">
                    <div className="checkbox-container">
                        <input
                            type="checkbox"
                            id="terms"
                            required
                            checked={agreed}
                            onChange={(e) => setAgreed(e.target.checked)}
                        />
                        <div>
                            <label htmlFor="terms" className="label-text">
                                I agree to the Terms of Use and Privacy Policy.
                            </label>
                            <p className="helper-text">
                                You must agree to continue using our platform.
                            </p>
                        </div>
                    </div>
                </div>
                <button type="submit">
                    Continue
                </button>
            </form>
        </div>
    );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ConsentForm />);

